323		trimmed := strings.TrimSpace(line)
324		if trimmed == "" {
325			return "", false
326		}
327	
328		rightTrimmed := strings.TrimRight(line, " \t")
329		leftTrimmed := strings.TrimLeft(rightTrimmed, " \t")
330	
331		if t.isCommentLine(leftTrimmed) {
332			return t.trimIndentPrefix(p, rightTrimmed), true
333		}
334	
335		return trimmed, true
