342	func (t *triviaEmitter) trimIndentPrefix(p *printer, line string) string {
343		if p == nil {
344			return strings.TrimLeft(line, " \t")
345		}
346	
347		max := int(p.opts.tabWidth) * p.indent
348		if max <= 0 {
349			return line
350		}
351	
352		idx := 0
353		for idx < len(line) && max > 0 {
354			switch line[idx] {
355			case ' ', '\t':
356				idx++
357				max--
358			default:
359				max = 0
360			}
361		}
362	
363		return line[idx:]
364	}
