func (t *triviaEmitter) emitListTriviaWith(p *printer, text string) {
	if text == "" {
		p.newline()

		return
	}

	if strings.TrimSpace(text) == "" {
		if strings.Count(text, "\n") >= 2 {
			p.newline()
		}

		p.newline()

		return
	}

	line := text
	rest := ""

	if idx := strings.IndexByte(text, '\n'); idx >= 0 {
		line = text[:idx]
		rest = text[idx+1:]
	}

	if inline := t.extractInlineComment(line); inline != "" {
		if !p.atLineStart {
			p.space()
		}

		p.write(inline)
		p.newline()
	} else {
		p.newline()
	}

