func (t *triviaEmitter) emitListCommentLinesWith(p *printer, text string) {
	if text == "" {
		return
	}

	lines := strings.Split(text, "\n")
	emptyCount := 0
	wroteLine := false

	for _, line := range lines {
		formatted, ok := t.formatTriviaLine(p, line)

		if !ok {
			emptyCount++
			continue
		}

		if emptyCount > 0 {
			p.newline()
			emptyCount = 0
		}

		if !p.atLineStart {
			p.space()
		}

		p.write(formatted)
		p.newline()
		wroteLine = true
	}

	if emptyCount >= 2 {
		p.newline()
		return
	}

	if !wroteLine && emptyCount > 0 {
		p.newline()
	}
